import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); String line = br.readLine(); if (line != null) { int t = Integer.parseInt(line.trim()); while (t-- > 0) { String n = br.readLine().trim(); if (n.length() > 0) { int first = n.charAt(0) - '0'; int last = n.charAt(n.length() - 1) - '0'; out.println(first + last); } } } out.flush(); out.close(); } }